from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.colors import darkblue
from reportlab.pdfbase.pdfmetrics import stringWidth
import os
from datetime import datetime


def generate_report(
    prediction_id,
    age,
    income,
    loan_amount,
    credit_score,
    probability,
    risk_level
):

    os.makedirs("reports", exist_ok=True)

    file_path = os.path.join(
        "reports",
        f"{prediction_id}.pdf"
    )

    doc = SimpleDocTemplate(file_path)

    styles = getSampleStyleSheet()

    title = styles["Heading1"]
    title.alignment = TA_CENTER
    title.textColor = darkblue

    heading = styles["Heading2"]
    normal = styles["BodyText"]

    story = []

    # ----------------------------
    # Title
    # ----------------------------

    story.append(
        Paragraph(
            "Smart Loan Risk Analytics Platform",
            title
        )
    )

    story.append(Spacer(1, 20))

    # ----------------------------
    # Prediction Details
    # ----------------------------

    story.append(Paragraph("<b>Prediction Details</b>", heading))
    story.append(Paragraph(f"Prediction ID : {prediction_id}", normal))
    story.append(
        Paragraph(
            f"Date : {datetime.now().strftime('%d-%m-%Y %H:%M:%S')}",
            normal,
        )
    )

    story.append(Spacer(1, 15))

    # ----------------------------
    # Customer Information
    # ----------------------------

    story.append(Paragraph("<b>Customer Information</b>", heading))

    story.append(Paragraph(f"Age : {age}", normal))
    story.append(Paragraph(f"Annual Income : ${income:,.2f}", normal))
    story.append(Paragraph(f"Loan Amount : ${loan_amount:,.2f}", normal))
    story.append(Paragraph(f"Credit Score : {credit_score}", normal))

    story.append(Spacer(1, 15))

    # ----------------------------
    # Prediction Result
    # ----------------------------

    story.append(Paragraph("<b>Prediction Result</b>", heading))

    story.append(
        Paragraph(
            f"Default Probability : {probability*100:.2f}%",
            normal
        )
    )

    story.append(
        Paragraph(
            f"Risk Level : {risk_level}",
            normal
        )
    )

    story.append(Spacer(1, 15))

    # ----------------------------
    # Recommendation
    # ----------------------------

    if risk_level == "Low":

        recommendation = "Loan Approval Recommended."

    elif risk_level == "Medium":

        recommendation = "Manual Verification Recommended."

    else:

        recommendation = "Loan Rejection Recommended."

    story.append(Paragraph("<b>Recommendation</b>", heading))
    story.append(Paragraph(recommendation, normal))

    story.append(Spacer(1, 25))

    # ----------------------------
    # Footer
    # ----------------------------

    story.append(
        Paragraph(
            "<b>Generated by Smart Loan Risk Analytics Platform</b>",
            normal,
        )
    )

    doc.build(story)

    return file_path